#!/usr/bin/env node
// docs/history/*.md → docs/logs.html (jay, 2026-08-13: "View All Logs page should show
// all the history file but it doesn't now" — the old target, docs/logs/summary.md, is a
// separate hand-maintained diary that stopped at 2026-06-15 and was never the same thing
// as the daily docs/history/YYYY-MM-DD-<repo>-history.md log jay actually keeps up.
//
// Source is docs/history/*.md alone — no separate list to fall out of sync. Each entry
// links to its already-converted page at docs/html/docs/history/<file>.html (generated by
// scripts/generate-docs-html.mjs, which runs across the whole repo).
import fs from 'node:fs';
import path from 'node:path';
import { renderRtdPage, escapeHtml } from './rtd-shell.mjs';

const REPO_ROOT = path.resolve(import.meta.dirname, '..');
const HISTORY_DIR = path.join(REPO_ROOT, 'docs', 'history');
const OUT_HTML = path.join(REPO_ROOT, 'docs', 'logs.html');

const DATE_RE = /^(\d{4}-\d{2}-\d{2})-?(.*)\.md$/;

function humanize(slug) {
  return slug
    .replace(/-history$/, '')
    .split('-')
    .filter(Boolean)
    .join(' ');
}

function titleFor(filename, raw) {
  const h1 = /^#\s+(.+)$/m.exec(raw)?.[1]?.trim() ?? '';
  // "# 2026-06-16" 처럼 날짜만 있는 제목은 정보가 없다 — 파일명 나머지로 대체.
  const bare = /^\d{4}-\d{2}-\d{2}$/.test(h1);
  if (h1 && !bare) return h1;
  const m = DATE_RE.exec(filename);
  const rest = m?.[2] ? humanize(m[2]) : '';
  return rest || filename.replace(/\.md$/, '');
}

// 그날의 브리핑 (jay, 2026-08-13: "should have brief description for the detail" — 목록에
// 날짜·링크만 있고 무슨 작업이었는지가 안 보였다). 소스마다 형식이 달라 문단을 안정적으로
// 뽑을 방법이 없으니, 대신 그날의 "### 작업 제목" 들(jay 자신의 "one titled block per
// action" 관례, ~/.claude/CLAUDE.md)을 모아 붙인다 — 이 헤딩들이 이미 그날 한 일의
// 목차이고, 모든 파일에 거의 항상 있다.
function briefFor(raw) {
  const heads = [...raw.matchAll(/^#{2,3}\s+(.+)$/gm)]
    .map((m) => m[1].trim())
    .filter((h) => !/^(summary|log|요약)\b/i.test(h));
  return heads;
}

// 파일명이 "-rabbit-history"/"-verex-history"로 명확히 밝히면 그게 정답이다 — 본문에서
// 상대 프로젝트가 몇 번 언급되든(예: 2026-08-12-rabbit-history.md 는 verex-api 설정도
// 같이 다뤄 "verex"가 여러 번 나오지만 파일명대로 rabbit 작업이다) 파일명이 우선한다.
// 파일명에 표시가 없는 초기 파일(예: 2026-05-07-phase1-w1-implementation.md)만
// 본문 언급 횟수로 판별한다.
function repoFor(filename, title, raw) {
  const lower = filename.toLowerCase();
  if (lower.includes('-rabbit-history') || lower.includes('-rabbit.md') || lower.includes('rabbit-history')) {
    return { label: 'Rabbit', color: '#16a34a' };
  }
  if (lower.includes('-verex-history') || lower.includes('-verex.md') || lower.includes('verex-history')) {
    return { label: 'Verex', color: '#d97706' };
  }
  if (title.toLowerCase().includes('verex')) return { label: 'Verex', color: '#d97706' };
  const mentions = (raw.match(/verex/gi) ?? []).length;
  if (mentions >= 3) return { label: 'Verex', color: '#d97706' };
  return { label: 'Rabbit', color: '#16a34a' };
}

const files = fs
  .readdirSync(HISTORY_DIR)
  .filter((f) => f.endsWith('.md'))
  .map((filename) => {
    const raw = fs.readFileSync(path.join(HISTORY_DIR, filename), 'utf8');
    const date = DATE_RE.exec(filename)?.[1] ?? '0000-00-00';
    const title = titleFor(filename, raw);
    return { filename, date, title, repo: repoFor(filename, title, raw), brief: briefFor(raw) };
  })
  .sort((a, b) => (a.date === b.date ? b.filename.localeCompare(a.filename) : b.date.localeCompare(a.date)));

const numbered = files.map((f, i) => ({ ...f, no: i + 1 }));

const navGroups = [
  {
    label: `전체 로그 (${numbered.length})`,
    items: numbered.map((f) => ({
      anchor: f.filename,
      text: `<span class="topic-no">${f.no}</span>${escapeHtml(f.title)}`,
      color: f.repo.color,
      statusLabel: f.repo.label,
    })),
  },
];

// 항목을 " · "로 이어붙이면 한 줄이 너무 길어 읽기 어렵다 (jay, 2026-08-13) — 각 작업을
// 자기 줄로 둔다. 많으면 앞 4개만 보여주고 나머지는 개수로만 남긴다.
const SHOWN_BRIEF_ITEMS = 4;
function briefHtml(brief) {
  if (!brief.length) return '';
  const shown = brief.slice(0, SHOWN_BRIEF_ITEMS);
  const restCount = brief.length - shown.length;
  const items = shown.map((h) => `<li>${escapeHtml(h)}</li>`).join('\n            ');
  const more = restCount > 0 ? `\n            <li class="meta">+${restCount}개 더</li>` : '';
  return `\n          <ul class="topic-brief">\n            ${items}${more}\n          </ul>`;
}

const rows = numbered
  .map(
    (f) => `        <li id="${escapeHtml(f.filename)}">
          <div class="topic-head"><span class="topic-no">${f.no}</span><span class="topic-title">${escapeHtml(f.title)}</span> <span class="badge" style="background:${f.repo.color}22; color:${f.repo.color};">${f.repo.label}</span></div>
          <p class="meta">${escapeHtml(f.date)}</p>${briefHtml(f.brief)}
          <p class="topic-link"><a href="html/docs/history/${escapeHtml(f.filename.replace(/\.md$/, '.html'))}">상세 &rarr;</a></p>
        </li>`
  )
  .join('\n');

const contentHtml = `    <article>
      <h1>전체 로그</h1>
      <p>일일 작업 이력 — <code>docs/history/</code> 아래 모든 항목, 최신순.</p>
      <ul class="topics no-divider">
${rows}
      </ul>
    </article>`;

fs.writeFileSync(
  OUT_HTML,
  renderRtdPage({
    title: '로그 — 전체',
    railTitle: 'Rabbit',
    railTitleHref: 'index.html',
    railSub: `로그 &mdash; 전체 항목 (${numbered.length})`,
    filterPlaceholder: '로그 검색',
    navGroups,
    railFoot: '<a href="index.html">&larr; 워크스페이스 인덱스</a>',
    srcLine: '원본: docs/history/*.md (scripts/generate-logs-html.mjs 로 자동 생성 — 이 파일이 아니라 히스토리 파일을 수정할 것)',
    contentHtml,
  }),
  'utf8'
);
console.log(`Logs: docs/logs.html (${numbered.length} entries)`);
